CREATE UNIQUE INDEX "IX_servicos_Nome" ON servicos ("Nome");

SELECT setval(
    pg_get_serial_sequence('servicos', 'Id'),
    GREATEST(
        (SELECT MAX("Id") FROM servicos) + 1,
        nextval(pg_get_serial_sequence('servicos', 'Id'))),
    false);

